def determine_winner(n, a):
    # Calculate the gcd of the array elements
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    # Calculate the gcd of all elements in the array
    gcd_value = a[0]
    for i in range(1, n):
        gcd_value = gcd(gcd_value, a[i])

    # If the gcd is zero, BitAryo wins
    if gcd_value == 0:
        return "BitAryo"
    # If the gcd is non-zero, BitLGM wins
    else:
        return "BitLGM"

