def solve(n, a):
    if n == 1:
        return "BitLGM" if a[0] % 2 == 0 else "BitAryo"
    elif n == 2:
        xor_sum = a[0] ^ a[1]
        return "BitLGM" if xor_sum != 0 else "BitAryo"
    else:  # n == 3
        return "BitLGM" if (a[0] ^ a[1] ^ a[2]) != 0 else "BitAryo"

